{
  "tasks": [
    {
      "task_id": "T1",
      "title": "销售数据整体概况",
      "business_question": "销售数据的总订单数、总销售额及平均单笔销售额是多少？",
      "priority": "P0",
      "priority_reason": "这是探索性分析的基础，提供数据集的整体规模和价值量级，是理解后续差异对比的前提。删除后无法回答核心问题中的'主要特征'。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_orders"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_order_value"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "按地区分析销售分布",
      "business_question": "不同地区的订单数量和销售额分布情况如何？",
      "priority": "P0",
      "priority_reason": "地区是主要的维度字段（unique_count=2），用于识别地域性的销售差异和集中趋势，符合探索主要差异的目标。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "region_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "region_total_sales"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "region_total_sales",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "按产品类别分析销售表现",
      "business_question": "不同产品类别的订单数量和销售总额分别是多少？",
      "priority": "P0",
      "priority_reason": "产品类别是关键业务维度（unique_count=2），分析其销售贡献有助于识别主力产品和潜在机会，属于主要特征的一部分。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "category_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "category_total_sales"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "category_total_sales",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T4",
      "title": "按城市分析销售差异",
      "business_question": "各城市的订单数量和销售总额排名是怎样的？",
      "priority": "P1",
      "priority_reason": "城市提供了比地区更细粒度的视角（unique_count=5），有助于发现具体的高价值或低效市场。虽非唯一核心维度，但对全面理解空间差异有重要补充作用。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "city_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "city_total_sales"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "city_total_sales",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
